@push('scripts')<script>const cards=[...document.querySelectorAll('.post-card')],search=document.getElementById('postSearch');function filter(){const q=search.value.toLowerCase();cards.forEach(c=>c.classList.toggle('hidden',!c.dataset.search.includes(q)))}search.addEventListener('input',filter);document.querySelectorAll('.sector').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sector').forEach(x=>x.classList.remove('border-white','bg-pitch-800'));b.classList.add('border-white','bg-pitch-800');cards.forEach(c=>c.classList.toggle('hidden',b.dataset.sector!=='ALL'&&c.dataset.sector!==b.dataset.sector))});const threadModal=document.getElementById('threadModal');document.querySelectorAll('.read-post').forEach(b=>b.onclick=()=>{modalTitle.textContent=b.dataset.title;modalBody.textContent=b.dataset.body;threadModal.classList.remove('hidden');threadModal.classList.add('flex')})</script>@endpush
